<template><q-page class="q-pa-lg"><div class="row justify-between items-center q-mb-lg"><div><h1 class="page-title">Customers</h1><p class="page-subtitle">Keep contact details and review purchase history.</p></div><q-btn color="primary" icon="person_add" label="Add customer" @click="open()"/></div><q-input v-model="search" outlined clearable label="Search name or phone" class="q-mb-md" @keyup.enter="page=1;load()"><template #append><q-btn flat round icon="search" aria-label="Search customers" @click="page=1;load()"/></template></q-input><q-banner v-if="error" class="bg-red-1 text-negative q-mb-md" role="alert">{{error}}</q-banner>
<q-table :rows="rows" :columns="columns" row-key="id" :loading="loading" flat bordered hide-pagination :pagination="{rowsPerPage:0}"><template #body-cell-actions="p"><q-td :props="p"><q-btn flat round icon="history" aria-label="Customer history" @click="historyId=p.row.id;historyPage=1;loadHistory()"/><q-btn flat round color="primary" icon="edit" aria-label="Edit customer" @click="open(p.row)"/><q-btn v-if="isAdmin" flat round color="negative" icon="delete_outline" aria-label="Delete customer" @click="remove(p.row)"/></q-td></template></q-table><div class="row justify-end q-mt-md"><q-pagination v-model="page" :max="last" :max-pages="5" direction-links @update:model-value="load"/></div>
<q-dialog v-model="dialog" persistent><q-card style="width:480px;max-width:95vw"><q-card-section class="text-h6">{{editing?'Edit customer':'New customer'}}</q-card-section><q-form @submit="save"><q-card-section class="q-gutter-md"><q-input v-model.trim="form.name" outlined label="Full name" maxlength="255" :rules="[v=>!!v||'Name is required']"/><q-input v-model.trim="form.phone" outlined label="Phone" maxlength="40"/><q-input v-model.trim="form.email" outlined label="Email (optional)" type="email" maxlength="255"/><q-input v-model.trim="form.address" outlined label="Address" maxlength="255"/><q-input v-model="form.notes" outlined type="textarea" label="Notes" maxlength="2000"/></q-card-section><q-card-actions align="right"><q-btn flat label="Cancel" :disable="saving" v-close-popup/><q-btn color="primary" label="Save customer" type="submit" :loading="saving"/></q-card-actions></q-form></q-card></q-dialog>
<q-dialog v-model="historyDialog"><q-card style="width:650px;max-width:95vw"><q-card-section class="row justify-between items-center"><span class="text-h6">{{history?.customer?.name}} · Purchase history</span><q-btn flat round icon="close" aria-label="Close history" v-close-popup/></q-card-section><q-list separator><q-item v-for="o in history?.orders?.data||[]" :key="o.id"><q-item-section>{{o.receipt_number||`Legacy #${o.id}`}}<q-item-label caption>{{dateTime(o.created_at)}} · {{o.status}}</q-item-label></q-item-section><q-item-section side>{{money(o.total_amount)}}</q-item-section></q-item></q-list><q-card-section v-if="!history?.orders?.data?.length">No purchases recorded.</q-card-section><q-card-section><q-pagination v-model="historyPage" :max="history?.orders?.last_page||1" :max-pages="5" @update:model-value="loadHistory"/></q-card-section></q-card></q-dialog>
</q-page></template>
<script setup lang="ts">
import{onMounted,ref}from'vue';import{useQuasar}from'quasar';import api,{errorMessage}from'../services/api';import{isAdmin}from'../services/auth';import{dateTime,money}from'../services/format'
const q=useQuasar(),rows=ref<any[]>([]),loading=ref(false),saving=ref(false),error=ref(''),search=ref(''),page=ref(1),last=ref(1),dialog=ref(false),editing=ref<number|null>(null),historyDialog=ref(false),history=ref<any>(null),historyId=ref(0),historyPage=ref(1)
const blank=()=>({name:'',phone:'',email:'',address:'',notes:''}),form=ref(blank())
const columns=[{name:'name',label:'Customer',field:'name',align:'left' as const},{name:'phone',label:'Phone',field:'phone',align:'left' as const},{name:'address',label:'Address',field:'address',align:'left' as const},{name:'orders_count',label:'Orders',field:'orders_count',align:'right' as const},{name:'actions',label:'Actions',field:'id',align:'right' as const}]
async function load(){loading.value=true;error.value='';try{const{data}=await api.get('/customers',{params:{page:page.value,search:search.value}});rows.value=data.data;last.value=data.last_page;if(page.value>last.value){page.value=last.value;await load()}}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
function open(row?:any){editing.value=row?.id||null;form.value=row?{name:row.name,phone:row.phone||'',email:row.email||'',address:row.address||'',notes:row.notes||''}:blank();dialog.value=true}
async function save(){if(saving.value)return;saving.value=true;try{if(editing.value)await api.patch(`/customers/${editing.value}`,form.value);else await api.post('/customers',form.value);dialog.value=false;await load();q.notify({type:'positive',message:'Customer saved.'})}catch(e){q.notify({type:'negative',message:errorMessage(e)})}finally{saving.value=false}}
function remove(row:any){q.dialog({title:'Delete customer?',message:`Delete ${row.name}? Customers with sales or delivery history are protected.`,cancel:true}).onOk(async()=>{try{await api.delete(`/customers/${row.id}`);await load()}catch(e){q.notify({type:'negative',message:errorMessage(e)})}})}
async function loadHistory(){try{history.value=(await api.get(`/customers/${historyId.value}`,{params:{page:historyPage.value}})).data;historyDialog.value=true}catch(e){q.notify({type:'negative',message:errorMessage(e)})}}onMounted(load)
</script>
